/* Public metadata cache only. Course records load by subject; student records never enter this cache. */
var CourseCatalogStore=(()=>{
 let manifestPromise=null;const shardPromises=new Map(),records=new Map(),refs=new Map();const institution=s=>CatalogDraftCore.canonical(s),key=(name,code)=>institution(name).toLowerCase()+'|'+CatalogDraftCore.norm(code);
 async function manifest(){if(!manifestPromise)manifestPromise=fetch('course-catalog/index.json').then(r=>{if(!r.ok)throw Error('Course catalog index unavailable.');return r.json()}).then(data=>{for(const [name,group]of Object.entries(data.institutions))for(const subject of Object.values(group.subjects))for(const code of subject.codes)refs.set(key(name,code),{institution:name,code,file:subject.file,units:group.units});return data}).catch(e=>{manifestPromise=null;throw e});return manifestPromise}
 async function load(name,codes){await manifest();const files=[...new Set(codes.map(code=>refs.get(key(name,code))?.file).filter(Boolean))];for(let i=0;i<files.length;i+=6)await Promise.all(files.slice(i,i+6).map(file=>{if(!shardPromises.has(file))shardPromises.set(file,fetch('course-catalog/'+encodeURIComponent(file)).then(r=>{if(!r.ok)throw Error('Course subject unavailable: '+file);return r.json()}).then(data=>{for(const row of data.records)records.set(key(row.institution,row.code),row)}).catch(e=>{shardPromises.delete(file);throw e}));return shardPromises.get(file)}));return codes.map(code=>records.get(key(name,code))).filter(Boolean)}
 async function loadClosure(name,codes){const wanted=new Set(codes.map(CatalogDraftCore.norm));let frontier=[...codes];for(let pass=0;pass<25&&frontier.length;pass++){const loaded=await load(name,frontier),next=[];for(const c of loaded)for(const dep of [...CatalogDraftCore.leaves(c.prerequisiteRule),...CatalogDraftCore.leaves(c.corequisiteRule)])if(!wanted.has(CatalogDraftCore.norm(dep.code))){wanted.add(CatalogDraftCore.norm(dep.code));next.push(dep.code)}frontier=next;if(wanted.size>500)throw Error('This prerequisite graph exceeds the review limit. Choose a smaller set of requirement clauses first.')}return[...records.values()].filter(c=>institution(c.institution)===institution(name)&&wanted.has(CatalogDraftCore.norm(c.code)))}
 return{manifest,load,loadClosure,allLoaded:()=>[...records.values()]};
})();
